// Theme Toggleconst themeToggle = document.getElementById('theme-toggle');const html = document.documentElement;// Check for saved theme preference or default to light modeconst savedTheme = localStorage.getItem('theme')|| 'light';html.classList.toggle('dark',savedTheme === 'dark');themeToggle.addEventListener('click',()=>{html.classList.toggle('dark');const isDark = html.classList.contains('dark');localStorage.setItem('theme',isDark ? 'dark':'light');});// Mobile Menu Toggleconst mobileMenuBtn = document.getElementById('mobile-menu-btn');const mobileMenu = document.getElementById('mobile-menu');if(mobileMenuBtn && mobileMenu){mobileMenuBtn.addEventListener('click',()=>{mobileMenu.classList.toggle('hidden');});// Close mobile menu when clicking a linkmobileMenu.querySelectorAll('a').forEach(link =>{link.addEventListener('click',()=>{mobileMenu.classList.add('hidden');});});}// Smooth scroll for navigation linksdocument.querySelectorAll('a[href^="#"]').forEach(anchor =>{anchor.addEventListener('click',function(e){e.preventDefault();const target = document.querySelector(this.getAttribute('href'));if(target){const offsetTop = target.offsetTop - 80;window.scrollTo({top:offsetTop,behavior:'smooth'});}});});// Intersection Observer for animationsconst observerOptions ={threshold:0.2,rootMargin:'0px 0px -100px 0px'};const observer = new IntersectionObserver((entries)=>{entries.forEach(entry =>{console.log('Observer entry:',{target:entry.target.tagName,classes:entry.target.className,isIntersecting:entry.isIntersecting,intersectionRatio:entry.intersectionRatio});if(entry.isIntersecting && !entry.target.classList.contains('visible')){console.log('Adding visible to:',entry.target);entry.target.classList.add('visible');}});},observerOptions);// Observe all elements with animation classesconst animatedElements = document.querySelectorAll('.fade-in-up,.scale-in,.slide-in-left,.slide-in-right,.hero-profile,.hero-name,.hero-title,.hero-subtitle,.hero-buttons,.hero-meta,.section-header,.card-scale,.slide-from-left,.slide-from-right,.card-fade-up,.alt-slide-left,.alt-slide-right,.award-highlight,.award-card,.contact-icon,.contact-text,.skill-tag');console.log('Found animated elements:',animatedElements.length);animatedElements.forEach(el =>{observer.observe(el);});// Observe sections separately for fade-in effectconst allSections = document.querySelectorAll('section');console.log('Found sections:',allSections.length);allSections.forEach(section =>{section.classList.add('fade-in');observer.observe(section);});// Navbar background on scrollconst nav = document.querySelector('nav');let lastScroll = 0;// Back to top button visibilityconst backToTopBtn = document.getElementById('back-to-top');window.addEventListener('scroll',()=>{const currentScroll = window.pageYOffset;// Show/hide back to top button(show after 500px scroll)if(backToTopBtn){if(currentScroll > 500){backToTopBtn.classList.remove('opacity-0','pointer-events-none');}else{backToTopBtn.classList.add('opacity-0','pointer-events-none');}}// Navbar shadow on scrollif(currentScroll > 100){nav.classList.add('shadow-md');}else{nav.classList.remove('shadow-md');}lastScroll = currentScroll;});// Active navigation link highlightingconst sections = document.querySelectorAll('section[id]');const navLinks = document.querySelectorAll('nav a[href^="#"]');window.addEventListener('scroll',()=>{let current = '';sections.forEach(section =>{const sectionTop = section.offsetTop - 100;const sectionHeight = section.clientHeight;if(window.pageYOffset >= sectionTop && window.pageYOffset < sectionTop + sectionHeight){current = section.getAttribute('id');}});navLinks.forEach(link =>{link.classList.remove('text-primary-600','font-medium');link.classList.add('text-gray-600');if(link.getAttribute('href')=== `#${current}`){link.classList.remove('text-gray-600');link.classList.add('text-primary-600','font-medium');}});});// Add subtle parallax effect to hero sectionconst heroSection = document.querySelector('section:first-of-type');if(heroSection){window.addEventListener('scroll',()=>{const scrolled = window.pageYOffset;if(scrolled < 500){heroSection.style.backgroundPositionY = `${scrolled * 0.3}px`;}});}// Console welcome messageconsole.log('%c Welcome to Ritesh Seth\'s Profile!','color:#0ea5e9;font-size:20px;font-weight:bold;');console.log('%c PhD Candidate in Computer Science @ IIIT Delhi','color:#666;font-size:14px;');